contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Valid claim input: if it reverts, it must be only because the caller
        // holds fewer unclaimed shares than requested (InsufficientShares), and
        // never for any other reason; if it succeeds, unclaimedShares must cover it.
        uint256 unclaimed = c.unclaimedShares(address(this));
        if (reverted) {
            assert(unclaimed < amount);
        } else {
            assert(unclaimed >= amount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        require(amount > 0 && amount <= type(uint128).max);

        // Fresh account: no deposits, no unclaimed shares, and its deposit
        // round (0) is below currentRound (1) with zero usdc balance.
        uint256 unclaimedBefore = c.unclaimedShares(address(this));

        bool reverted;
        // state-changing call must be top-level: claim is attempted once
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 unclaimedAfter = c.unclaimedShares(address(this));

        // General rule: a claim can only succeed if the caller's unclaimed
        // shares (including pending round conversion) cover the amount. For
        // an account with zero unclaimed shares and zero usdc balance, any
        // positive claim must revert and leave unclaimed shares at zero.
        assert(
            (unclaimedBefore == 0) == (unclaimedAfter == 0)
            && reverted == (unclaimedBefore < amount)
        );
    }

    receive() external payable {}
}

